Корневой контейнер компоновки представляет элемент ConstraintLayout . Сверху в нем определены два текстовых поля TextView: одно для вывода результата вычислений и одно для вывода текущего знака операции.



Затем идет элемент EditText, предназначенный для ввода чисел.



И далее расположены четыре элемента LinearLayout с горизонтальными рядами кнопок. Чтобы все кнопки занимали равное пространство внутри контейнера, для них установлены атрибуты `android:layout_weight="1"` и `android:layout_width="0dp"`.



Для каждой кнопки установлен идентификатор, чтобы в коде можно было прикрепить к ней определенный обработчик нажатия.






Теперь изменим класс **MainActivity**:



```java

package com.enoobis.calculator;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.EditText;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    TextView resultField; // текстовое поле для вывода результата
    EditText numberField;   // поле для ввода числа
    TextView operationField;    // текстовое поле для вывода знака операции
    Double operand = null;  // операнд операции
    String lastOperation = "="; // последняя операция
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        // получаем все поля по id из activity_main.xml
        resultField = findViewById(R.id.resultField);
        numberField = findViewById(R.id.numberField);
        operationField = findViewById(R.id.operationField);

        findViewById(R.id.add).setOnClickListener((view)->onOperationClick("+"));
        findViewById(R.id.sub).setOnClickListener((view)->onOperationClick("-"));
        findViewById(R.id.mul).setOnClickListener((view)->onOperationClick("*"));
        findViewById(R.id.div).setOnClickListener((view)->onOperationClick("/"));
        findViewById(R.id.eq).setOnClickListener((view)->onOperationClick("="));

        findViewById(R.id.n0).setOnClickListener((view)->onNumberClick("0"));
        findViewById(R.id.n1).setOnClickListener((view)->onNumberClick("1"));
        findViewById(R.id.n2).setOnClickListener((view)->onNumberClick("2"));
        findViewById(R.id.n3).setOnClickListener((view)->onNumberClick("3"));
        findViewById(R.id.n4).setOnClickListener((view)->onNumberClick("4"));
        findViewById(R.id.n5).setOnClickListener((view)->onNumberClick("5"));
        findViewById(R.id.n6).setOnClickListener((view)->onNumberClick("6"));
        findViewById(R.id.n7).setOnClickListener((view)->onNumberClick("7"));
        findViewById(R.id.n8).setOnClickListener((view)->onNumberClick("8"));
        findViewById(R.id.n9).setOnClickListener((view)->onNumberClick("9"));
        findViewById(R.id.comma).setOnClickListener((view)->onNumberClick(","));
    }
    // сохранение состояния
    @Override
    protected void onSaveInstanceState(Bundle outState) {
        outState.putString("OPERATION", lastOperation);
        if(operand!=null)
            outState.putDouble("OPERAND", operand);
        super.onSaveInstanceState(outState);
    }
    // получение ранее сохраненного состояния
    @Override
    protected void onRestoreInstanceState(@NonNull Bundle savedInstanceState) {
        super.onRestoreInstanceState(savedInstanceState);
        lastOperation = savedInstanceState.getString("OPERATION");
        operand= savedInstanceState.getDouble("OPERAND");
        resultField.setText(operand.toString());
        operationField.setText(lastOperation);
    }
    // обработка нажатия на числовую кнопку
    public void onNumberClick(String number){
        numberField.append(number);
        if(lastOperation.equals("=") && operand!=null){
            operand = null;
        }
    }
    // обработка нажатия на кнопку операции
    public void onOperationClick(String op){

        String number = numberField.getText().toString();
        // если введенно что-нибудь
        if(number.length()>0){
            number = number.replace(',', '.');
            try{
                performOperation(Double.valueOf(number), op);
            }catch (NumberFormatException ex){
                numberField.setText("");
            }
        }
        lastOperation = op;
        operationField.setText(lastOperation);
    }

    private void performOperation(Double number, String operation){

        // если операнд ранее не был установлен (при вводе самой первой операции)
        if(operand ==null){
            operand = number;
        }
        else{
            if(lastOperation.equals("=")){
                lastOperation = operation;
            }
            switch(lastOperation){
                case "=":
                    operand =number;
                    break;
                case "/":
                    if(number==0){
                        operand =0.0;
                    }
                    else{
                        operand /=number;
                    }
                    break;
                case "*":
                    operand *=number;
                    break;
                case "+":
                    operand +=number;
                    break;
                case "-":
                    operand -=number;
                    break;
            }
        }
        resultField.setText(operand.toString().replace('.', ','));
        numberField.setText("");
    }
}
```



Разберем этот код. Вначале в методе `onCreate()` получаем все поля из activity_main.xml, текст которых будет изменяться:



```java

resultField = findViewById(R.id.resultField);
numberField = findViewById(R.id.numberField);
operationField = findViewById(R.id.operationField);
```



Далее для каждой кнопки назначаем определенный обработчик нажатия - в зависимости от типа кнопки это либо метод `onNumberClick`, в который передается нажатое число, либо `onOperationClick`, в который передается знак операции.




Результат операции будет попадать в переменную operand, которая представляет тип Double, а знак операции - в переменную lastOperation:



```java

Double operand = null;
String lastOperation = "=";
```



Так как при переходе от портретной ориентации к альбомной или наоборот мы можем потерять все введенные данные, то чтобы их не потерять, мы их сохраняем в методе `onSaveInstanceState()` и обратно получаем в методе `onRestoreInstanceState()`.



При нажатии на числовую кнопку будет вызываться метод `onNumberClick`, в котором добавляем введенную цифру или знак запятой к тексту в поле numberField:



```java

numberField.append(number);

if(lastOperation.equals("=") && operand!=null){
    operand = null;
}
```



При этом если последняя операция представляла собой получение результата (знак "равно"), то мы сбрасываем переменную operand.



В методе `onOperationClick` происходит обработка нажатия на кнопку со знаком операции:



```java

String number = numberField.getText().toString();
if(number.length()>0){
	number = number.replace(',', '.');
	try{
		performOperation(Double.valueOf(number), op);
	}catch (NumberFormatException ex){
		numberField.setText("");
	}
}
lastOperation = op;
operationField.setText(lastOperation);
```



Здесь получаем ранее введенное число и введенную операцию и передаем их в метод `performOperation()`. Так как в метод передается не просто строка, а число Double, то нам надо преобразовать строку в чсло. И поскольку теоретически могут быть введены нечисловые символы, то для отлова исключения, которое может возникнуть при преобразовании используется конструкция try...catch.



Кроме того, так как разделителем целой и дробной части в Double в java является точка, то нам надо заменить запятую на точку, так как предполагается, что мы используем в качестве разделителя запятую.



А методе `performOperation()` выполняем собственно операцию. При вводе первой операции, когда операнд еще не установлен, мы просто устанавливаем операнд:



```java

if(operand ==null){
    operand = number;
}
```



При вводе второй и последующих операций применяем предыдущую операцию, знак которой хранится в переменной lastOperation, к операнду operand и второму числу, которое было введено в числовое поле. Полученный результат операции сохраняем в переменной operand.

Для создания простых уведомлений в Android используется класс **Toast**. Фактически Toast представляет всплывающее окно с некоторым текстом, которое отображается в течение некоторого времени.

Объект Toast нельзя создать в коде разметки xml, например, в файл activity_main.xml . Toast можно использовать только в коде java.

Так, определим в файле разметки activity_main.xml кнопку:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <Button
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Click"
        android:onClick="onClick"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

У кнопки установлен обработчик нажатия - метод onClick. Определим его в коде MainActivity:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.Toast;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_main);
    }

    public  void onClick(View view){
        Toast toast = Toast.makeText(this, "Hello Android!",Toast.LENGTH_LONG);
        toast.show();
    }
}
```

В обработчике отображается всплывающее окно. Для его создания применяется метод **Toast.makeText()**, в который передается три параметра: текущий контекст (текущий объект activity), отображаемый текст и время отобажения окна.

В качестве времени показа окна мы можем использовать целочисленное значение - колическо миллисекунд или встроенные константы **Toast.LENGTH_LONG** (3500 миллисекунд) и **Toast.LENGTH_SHORT** (2000 миллисекунд).

Для самого отображения окна вызывается метод **show()**:

![toast в android и java](/uploads/course-lectures/ffbf7421e5043e7c2eac56a0d9892a64e9219dad.png)

По умолчанию окно отображается внизу интерфейса с центрированием по центру. Но мы можем кастомизировать позиционирование окна с помощью методов **setGravity()** и **setMargin()**. Так, изменим метод onClick:

```java
public  void onClick(View view){

	Toast toast = Toast.makeText(this, "Hello Android!", Toast.LENGTH_LONG);
    toast.setGravity(Gravity.TOP, 0,160);	// import android.view.Gravity;
    toast.show();
}
```

Первый параметр метода setGravity указывает, в какой части контейнера надо позиционировать Toast, второй и третий параметр устанавливают отступы от этой позиции по горизонтали и вертикали сооветственно:

![позиционирование toast в android и java](/uploads/course-lectures/714237b3f1a8a0ef46506c71a24746ff4b6deee9.png)

Метод **setMargin()** принимает два параметра: отступ от левой границы контейнера в процентах от шиирины контейнера и отступ от верхней границы в процентах от длины контейнера.

Элемент **Snackbar** в некотором роде похож на Toast: он также позволяет выводить всплывающие сообщения, но теперь сообщения растягиваются по ширине экрана.

Для применения Snackbar добавим в файл **activity_main.xml** определение кнопки, по нажатию на которую будет появляться Snackbar:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <Button
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Click"
        android:onClick="onClick"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

Здесь определена кнопка, по нажатию на которую будет оображаться сообщение.

И также изменим класс **MainActivity**:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.view.View;

import com.google.android.material.snackbar.Snackbar;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    public  void onClick(View view){
        Snackbar.make(view, "Hello Android", Snackbar.LENGTH_LONG)
                .show();
    }
}
```

Snackbar создается с помощью метода **make()**, в который передаются три параметра: объект View, к которому прикрепляется всплывающее ообщение, само сообщение в виде строки и параметр, который указывает, сколько будет отображаться сообщение. Последний параметр может принимать числовое значение - количество миллисекунд, либо одну из трех констант: **Snackbar.LENGTH_INDEFINITE** (отображение в течение неопределенного периода времени), **Snackbar.LENGTH_LONG** (долгое отображение) или **Snackbar.LENGTH_SHORT** (недолгое отображение).

После создания Snackbar отображается с помощью метода **show**:

![snackbar в android и java](/uploads/course-lectures/52443dbd10551ab593c47160a85daefbc8b0ba90.png)

При этом в отличие от Toast мы не можем повлиять на позицию сообщения, оно отображается внизу экрана и занимает всю нижнюю часть.

### Прикрепление обработчика события

Snackbar позволяет добавить виджету действие, чтобы пользователь мог как-то прореагировать на сообщение. Например, изменим код MainActivity следующим образом:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.view.View;
import android.widget.Toast;

import com.google.android.material.snackbar.Snackbar;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    public  void onClick(View view){
        Snackbar snackbar = Snackbar.make(view, "Hello Android", Snackbar.LENGTH_LONG);

		snackbar.setAction("Next...", new View.OnClickListener (){
            @Override
            public void onClick(View v) {
                Toast toast = Toast.makeText(getApplicationContext(), "Next clicked!",Toast.LENGTH_LONG);
                toast.show();
            }
        });
        snackbar.show();
    }
}
```

Для добавления действия у Snackbar применяется метод **setAction()**. Первый параметр представляет текст кнопки в сообщении, на которую может нажать пользователь - в данном случае это "Next...". Второй параметр представляет реализацию интерфейса **View.OnClickListener** (тот же самый, который используется для обработки нажатия кнопки). В методе **onClick()** сообственно выполняем действия, которые вызываются при нажатии на кнопку в сообщении. В данном случае для простоты просто отображаем всплывающее сообщение в виде объекта Toast

![обработка нажатия click в snackbar в android и java](/uploads/course-lectures/59bb2d661ffb46eebf80c882d1399dbc689029da.png)

### Настройка визуального вида

Ряд методов Snackbar позволяет настроить внешний вид:

- setTextColor() : настраивает цвет текста

- setBackgroundTint() : настраивает цвет фона

- setActionTextColor() : настраивает цвет текста кнопки в всплывающем сообщении

```java
snackbar.setTextColor(0XFF81C784);
snackbar.setBackgroundTint(0XFF555555);
snackbar.setActionTextColor(0XFF0277BD);
```

![настройка визуального вида snackbar в android и java](/uploads/course-lectures/42efde21d76bdce215eaf9ac2d65ff180e3b3752.png)

Элементы Checkbox представляют собой флажки, которые могут находиться в отмеченном и неотмеченном состоянии. Флажки позволяют производить множественный выбор из нескольких значений. Итак, определим в файле разметки **activity_main.xml** элемент CheckBox:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <TextView android:id="@+id/selection"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

    <CheckBox android:id="@+id/enabled"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Включить"
        android:textSize="26sp"

        android:onClick="onCheckboxClicked"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/selection"/>


</androidx.constraintlayout.widget.ConstraintLayout>
```



Атрибут `android:onClick`, как и в случае с простыми кнопками, позволяет задать обработчик нажатия на флажок. Определим обработчик нажатия в коде MainActivity:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.CheckBox;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    public void onCheckboxClicked(View view) {
        // Получаем флажок
        CheckBox checkBox = (CheckBox) view;
        TextView selection = findViewById(R.id.selection);
        // Получаем, отмечен ли данный флажок
        if(checkBox.isChecked()) {
            selection.setText("Включено");
            checkBox.setText("Выключить");
        }
        else {
            selection.setText("Выключено");
            checkBox.setText("Включить");
        }
    }
}
```



В качестве параметра в обработчик нажатия onCheckboxClicked передается нажатый флажок. Обработчик срабатывает при каждом нажатии на checkBox. То есть и когда мы устанавливаем флажок, и когда мы снимем отметку. С помощью метода **isChecked()** можно узнать, выделен ли флажок - в этом случае метод возвращает true.



![элемент checkbox в android и java](/uploads/course-lectures/3955872eaf793d7527aa3a7499991c51acccf03d.png)







Подобным образом можно использовать несколько флажков:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <TextView android:id="@+id/selection"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

    <CheckBox android:id="@+id/java"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Java"
        android:textSize="26sp"

        android:onClick="onCheckboxClicked"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/selection"/>

    <CheckBox android:id="@+id/kotlin"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Kotlin"
        android:textSize="26sp"

        android:onClick="onCheckboxClicked"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/java"/>

</androidx.constraintlayout.widget.ConstraintLayout>
```



На каждый флажок можно повесить свой обработчик нажатия. А можно сделать один, как в данном случае. В этом случае мы можем обработать несколько флажков в коде java с помощью конструкции `switch...case`



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.CheckBox;
import android.widget.TextView;
import android.widget.Toast;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    public void onCheckboxClicked(View view) {
        // Получаем флажок
        CheckBox checkBox = (CheckBox) view;
        // Получаем, отмечен ли данный флажок
        boolean checked = checkBox.isChecked();

        TextView selection = findViewById(R.id.selection);

         // Смотрим, какой именно из флажков отмечен
        switch(view.getId()) {
            case R.id.java:
                if (checked)
                    Toast.makeText(this, "Вы выбрали Java ",Toast.LENGTH_LONG).show();
                break;
            case R.id.kotlin:
                if (checked)
                    Toast.makeText(this, "Вы выбрали Kotlin",Toast.LENGTH_LONG).show();
                break;
            default:
                selection.setText("");
        }
    }
}
```



С помощью конструкции switch...case можно получить id нажатого флажка и выполнить соответствующие действия.



![элемент checkbox в android](/uploads/course-lectures/72ff31512d269a2e4e172b698be377a0d631192c.png)



Правда, если нам просто надо взять текст из выбранного флажка, то необязательно в данном случае использовать конструкцию switch, так как мы можем сократить весь код следующим образом:



```java

public void onCheckboxClicked(View view) {
    // Получаем флажок
    CheckBox language = (CheckBox) view;
    // Получаем, отмечен ли данный флажок
    TextView selection = findViewById(R.id.selection);
    if(language.isChecked())
        selection.setText(language.getText());
}
```



Однако в данном случае остается проблема: в текстовом поле отображается только один выделенный элемент. Изменим код MainActivity, чтобы отображать оба выделенных элемента:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.CheckBox;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }

    public void onCheckboxClicked(View view) {

        // Получаем флажки
        CheckBox java = findViewById(R.id.java);
        CheckBox kotlin = findViewById(R.id.kotlin);
        String selectedItems = "";
        if(java.isChecked())
            selectedItems +=java.getText() + " ";
        if(kotlin.isChecked())
            selectedItems +=kotlin.getText();

        TextView selection = findViewById(R.id.selection);
        selection.setText(selectedItems);
    }
}
```



![выбор checkbox в android](/uploads/course-lectures/c322742bd49dd2081a4607f67519b1be29df041f.png)



### OnCheckedChangeListener



Применение слушателя **OnCheckedChangeListener** представляет альтернативный способ отслеживания изменения флажка. Этот слушатель срабатывает, когда мы устанавливаем или убираем отметку на флажке. Например, определим следующий checkbox:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <TextView android:id="@+id/selection"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

    <CheckBox android:id="@+id/enabled"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Включить"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/selection"/>

</androidx.constraintlayout.widget.ConstraintLayout>
```



В коде MainActivity подключим обработчик изменения состояния:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.CheckBox;
import android.widget.CompoundButton;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        TextView selection = findViewById(R.id.selection);
        CheckBox enableBox = findViewById(R.id.enabled);

        enableBox.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {
            public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {

                if(isChecked) {
                    selection.setText("Включено");
                    buttonView.setText("Выключить");
                }
                else {
                    selection.setText("Выключено");
                    buttonView.setText("Включить");
                }
            }
        });
    }
}
```



Слушатель OnCheckedChangeListener определен в базовом классе **CompoundButton** и определяет один метод - **onCheckedChanged**. Первый параметр этого метода `buttonView` - сам измененный флажок CheckBox. А второй параметр `isChecked` указывает, отмечен ли флажок.



При изменении состояния флажка будет выводиться во всплывающем окне соответствующее уведомление:



![checkbox и oncheckedchangelistener в android](/uploads/course-lectures/3955872eaf793d7527aa3a7499991c51acccf03d.png)

**ToggleButton** подобно элементу CheckBox может пребывать в двух состояниях: отмеченном и неотмеченном, причем для каждого состояния мы можем отдельно установить свой текст. Например, определим следующий элемент ToggleButton:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <ToggleButton
        android:id="@+id/toggle"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textOn="Включено"
        android:textOff="Выключено"
        android:onClick="onToggleClicked"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

Атрибуты `android:textOn` и `android:textOff` задают текст кнопки в отмеченном и неотмеченном состоянии соответственно. И также, как и для других кнопок, мы можем обработать нажатие на элемент с помощью события `onClick`. В этом случае определим в классе Activity обработчик события:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.Toast;
import android.widget.ToggleButton;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }
    public void onToggleClicked(View view) {

        // включена ли кнопка
        boolean on = ((ToggleButton) view).isChecked();
        if (on) {
            // действия если включена
            Toast.makeText(this, "Свет включен", Toast.LENGTH_LONG).show();
        } else {
            // действия, если выключена
            Toast.makeText(this, "Свет выключен!", Toast.LENGTH_LONG).show();
        }
    }
}
```

![togglebutton в android в отмеченном состоянии](/uploads/course-lectures/1cdab48df6b884b506b1e93059e85305f330e7cc.png)

Создание элемента ToggleButton в коде java:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import androidx.constraintlayout.widget.ConstraintLayout;

import android.os.Bundle;
import android.view.View;
import android.widget.Toast;
import android.widget.ToggleButton;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);
        ConstraintLayout layout = new ConstraintLayout(this);
        ConstraintLayout.LayoutParams layoutParams = new ConstraintLayout.LayoutParams
                (ConstraintLayout.LayoutParams.WRAP_CONTENT, ConstraintLayout.LayoutParams.WRAP_CONTENT);
        ToggleButton toggleButton = new ToggleButton(this);
        toggleButton.setTextOff("Выключено");
        toggleButton.setTextOn("Включено");
        toggleButton.setText("Выключено");
        toggleButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                boolean on = ((ToggleButton) view).isChecked();

                if (on) {
                    Toast.makeText(getApplicationContext(), "Свет включен", Toast.LENGTH_LONG).show();
                } else {
                    Toast.makeText(getApplicationContext(), "Свет выключен!", Toast.LENGTH_LONG).show();
                }
            }
        });
        layoutParams.leftToLeft = ConstraintLayout.LayoutParams.PARENT_ID;
        layoutParams.topToTop = ConstraintLayout.LayoutParams.PARENT_ID;
        layout.addView(toggleButton);
        setContentView(layout);
    }
}
```

Схожую с флажками функциональность предоставляют переключатели, которые представлены классом **RadioButton**. Но в отличие от флажков единовременно в группе переключателей мы можем выбрать только один переключатель.



Чтобы создать список переключателей для выбора, вначале надо создать объект **RadioGroup**, который будет включать в себя все переключатели:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

   <TextView android:id="@+id/selection"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

    <RadioGroup
        android:id="@+id/radios"
        android:layout_width="match_parent"
        android:layout_height="wrap_content"
        android:orientation="vertical"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/selection"
        >

        <RadioButton android:id="@+id/java"
            android:layout_width="wrap_content"
            android:layout_height="wrap_content"
            android:text="Java" />
        <RadioButton android:id="@+id/kotlin"
            android:layout_width="wrap_content"
            android:layout_height="wrap_content"
            android:text="Kotlin" />
    </RadioGroup>
</androidx.constraintlayout.widget.ConstraintLayout>
```



Поскольку класс `RadioGroup` является производным от `LinearLayout`, то мы также можем задать вертикальную или горизонтальную ориентацию списка, при том включив в него не только собственно переключатели, но и другие объекты, например, кнопку или TextView.



В классе MainActivity определим обработку выбора переключателей:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.view.View;
import android.widget.RadioButton;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {
    TextView selection;
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        selection = findViewById(R.id.selection);
        // устанавливаем обработчики для кнопок
        findViewById(R.id.java).setOnClickListener((view)->onRadioButtonClicked(view));
        // устанавливаем обработчики для кнопок
        findViewById(R.id.kotlin).setOnClickListener((view)->onRadioButtonClicked(view));
    }
    public void onRadioButtonClicked(View view) {
        RadioButton radio = (RadioButton) view;
        // если переключатель отмечен
        boolean checked = radio.isChecked();
        // получаем текст нажатой радиокнопки
        String text = radio.getText().toString();
        // Получаем нажатый переключатель
        switch(text) {
            case "Java":
                if (checked) selection.setText("Выбрана Java");
                break;
            case "Kotlin":
                if (checked) selection.setText("Выбран Kotlin");
                break;
        }
    }
}
```



![элемент radiobutton в android 7](/uploads/course-lectures/71705659a7bd92e038061a189e04df46feadc5f8.png)



### OnCheckedChangeListener



Кроме обработки нажатия на каждый отдельный переколючатель мы можем в целом повесить на весь RadioGroup с его переключателями слушатель **OnCheckedChangeListener** и обрабатывать в нем нажатия. Для этого уберем из разметки у элемента RadioGroup определим id:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

   <TextView android:id="@+id/selection"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

    <RadioGroup
        android:id="@+id/radios"
        android:layout_width="match_parent"
        android:layout_height="wrap_content"
        android:orientation="vertical"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/selection">
        <RadioButton android:id="@+id/java"
            android:layout_width="wrap_content"
            android:layout_height="wrap_content"
            android:text="Java" />
        <RadioButton android:id="@+id/kotlin"
            android:layout_width="wrap_content"
            android:layout_height="wrap_content"
            android:text="Kotlin" />
    </RadioGroup>
</androidx.constraintlayout.widget.ConstraintLayout>
```



Далее в коде MainActivity повесим на объект `RadioGroup` слушатель **OnCheckedChangeListener**:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.RadioButton;
import android.widget.RadioGroup;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {
    TextView selection;
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        selection = findViewById(R.id.selection);
        // получаем объект RadioGroup
        RadioGroup radios = findViewById(R.id.radios);
        // обработка переключения состояния переключателя
        radios.setOnCheckedChangeListener((radiogroup, id)-> {

            // получае выбранную кнопку
            RadioButton radio = findViewById(id);
            switch (radio.getText().toString()) {
                case "Java":
                    selection.setText("Выбрана Java");
                    break;
                case "Kotlin":
                    selection.setText("Выбран Kotlin");
                    break;
                default:
                    break;
            }
        });
    }
}
```



Слушатель RadioGroup.OnCheckedChangeListener определяет метод **onCheckedChanged()**, в который передается объект RadioGroup и id выделенного переключателя. Далее также мы можем получить по id выбранную радиокнопку и выполнить определенную обработку.

**TimePicker** представляет виджет для выбора времени, который может отображать время либо в 24-часовом, либо в 12-часовом формате.

Среди атрибутов TimePicker следует выделить **timePickerMode**, который позволяет режим отображения и может принимать одно из двух значений: **clock** (отображение в виде часов) и **spinner** (отображение в виде спиннера).

Среди методов TimePicker можно отметить следующие:

- `int getHour()` : возвращает час (в 24-часом формате)

- `int getMinute()` : возвращает минуты

- `boolean is24HourView()` : возвращает true, если используется 24-часовой формат

- `void setHour(int hour)` : устанавливает час для TimePicker

- `void setIs24HourView(Boolean is24HourView)` : устанавливает 24-часовой формат

- `void setMinute(int minute)` : устанавливает минуты

- `void setOnTimeChangedListener(TimePicker.OnTimeChangedListener onTimeChangedListener)` : устанавливает слушатель изменения времени в TimePicker в виде объекта TimePicker.OnTimeChangedListener

Определим TimePicker в **activity_main.xml**:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent"
    android:padding="16dp">

    <TextView android:id="@+id/timeTextView"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:textSize="26sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

    <TimePicker android:id="@+id/timePicker"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toBottomOf="@+id/timeTextView" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

Применим некоторые методы TimePicker для управления его поведением:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.TextView;
import android.widget.TimePicker;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        TextView timeTextView = findViewById(R.id.timeTextView);
        TimePicker timePicker = findViewById(R.id.timePicker);

        timePicker.setOnTimeChangedListener(new TimePicker.OnTimeChangedListener() {
            @Override
            public void onTimeChanged(TimePicker view, int hourOfDay, int minute) {

                timeTextView.setText("Время: " + hourOfDay + ":" + minute);
                // или так
                // timeTextView.setText("Время: " + view.getHour() + ":" + view.getMinute());
            }
         });
    }
}
```

Для добавления слушателя изменения времени в TimePicker применяется метод `setOnTimeChangedListener()`, в который передается объект **TimePicker.OnTimeChangedListener**. Он имеет один метод - **onTimeChanged()**, который вызывается при каждом изменении времени в TimePicker. Этот метод принимает три параметра - сам элемент TimePicker, `hourOfDay` - установленный час и `minute` - установленные минуты. В данном случае просто передаем значение выбранного времени в TextView.

![ontimechangedlistener в timepicker в android и java](/uploads/course-lectures/6a4def31213484297d93e1d19734ca3ee56900d1.png)

По умолчанию TimePicker отображается в режиме "clock" или часы. Применим режим "spinner":

```xml
<TimePicker android:id="@+id/timePicker"
	android:layout_width="wrap_content"
	android:layout_height="wrap_content"
	android:timePickerMode="spinner"
	app:layout_constraintLeft_toLeftOf="parent"
	app:layout_constraintTop_toBottomOf="@+id/timeTextView" />
```

![spinner в timepicker в android и java](/uploads/course-lectures/7d95f49d167afe2641c3c0d7d3cc1672d7453173.png)

Ресурсы строк - один из важных компонентов приложения. Мы используем их при выведении названия приложения, различного текста, например, текста кнопок и т.д.



XML-файлы, представляющие собой ресурсы строк, находятся в проекте в папке **res/values**. По умолчанию ресурсы строк находятся в файле **strings.xml**, который может выглядеть следующим образом:



```xml

<resources>
    <string name="app_name">ViewApp</string>
</resources>
```



![ресурсы строк в android и java](/uploads/course-lectures/006b00d61c7308590e04d354a8b85b1e3edc0138.png)



В самом простом виде этот файл определяет один ресурс "app_name", который устанавливает название приложения, которое мы видим в заголовке приложения на экране устройства. Но естественно мы можем определить любые строковые ресурсы. Каждый отдельный ресурс определяется с помощью элемента **string**, а его атрибут `name` содержит название ресурса.



Затем в приложении в файлах кода мы можем ссылаться на эти ресурсы:



```java

R.string.app_name
```



Например, в коде Java:



```java

String application_name =  getResources().getString(R.string.app_name);
```



Либо в xml-файле:



```xml

@string/app_name
```



Например, изменим файл **res/values/strings.xml** следующим образом:



```xml

<resources>
    <string name="app_name">ViewApp</string>
    <string name="message">Hello Android!</string>
</resources>
```



Здесь добавлен ресурс `message` со значением "Hello Android!".



Теперь используем ресурс в файле activity_main.xml:



```xml

<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <TextView
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="@string/message"
        android:textSize="30sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```



С помощью выражения `@string/message` передаем атрибуту `android:text` значение из ресурса.



![ресурсы строк из strings.xml в android studio и java](/uploads/course-lectures/827dee234491a6c65db5d37656ef4a402605e2c1.png)



Аналогично мы могли бы использовать ресурс в коде Activity:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        // получаем элемент textView
        TextView textView = findViewById(R.id.textView);
        // переустанавливаем у него текст
        textView.setText(R.string.message);
    }
}
```



Если нам в принципе надо получить ресурс в коде Java (необязательно для установки текста в TextView), то в этом случае можно использовать метод `getResources().getString(идентификатор_ресурса)`



```java
String message = getResources().getString(R.string.message);
```



Хотя по умолчанию для ресурсов строк применяется файл strings.xml, но разработчики могут добавлять дополнительные файлы ресурсов в каталог проекта res/values . При этом достаточно соблюдать структуру файла: он должен иметь корневой узел ` ` и иметь один или несколько элементов ` `.



Так, нажмем на папку **res/values** правой кнопкой мыши и в появившемся списке выберем пункт **New -> Value Resource File**:



![добавление ресурса строк в android studio](/uploads/course-lectures/bb350cc24fd6c6cbbef98205865e65ae53feaf80.png)



Причем следует отметить, что данный тип файлов будет характерен для любого типа ресурсов, который добавляется в папку **res/values**.



После этого нам будет предложено определить для файла имя:



![string resources in android studio](/uploads/course-lectures/10766e56e80c20218d3a2abc76933fcc550e797f.png)



Назовем, к примеру, **headers** (название файла произвольное), а для всех остальных полей оставим значения по умолчанию. И в папку **res/values** будет добавлен новый файл headers.xml. Определим в нем пару ресурсов:



```xml

<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="welcome">Добро пожаловать</string>
    <string name="click_button">Нажмите на кнопку</string>
</resources>
```



И после этого мы сможем использовать определенные здесь ресурсы в коде Activity или в файле layout.



### Форматирование строк



Android позволяет применять к ресурсам строк форматирование. Например, изменим файл strings.xml:



```xml

<resources>
    <string name="app_name">ViewApp</string>
    <string name="message">Hello Android!</string>
    <string name="welcome_message">Добро пожаловать %1$s! Уже %2$d : %3$d</string>
</resources>
```



Третий ресурс - welcome_message представляет строку с форматированием. Так, она содержит такие символы как %1$s, %2$d и %3$d. Что они означают? `%1$s` указывает, что это первый аргумент, а символ "s" говорит, что этот аргумент представляет строку. `%2$d` представляет второй аргумент, а символ "d" в конце указывает, что это будет целое число. Аналогично `%3$d` указывает, что это третий аргумент, который представляет целое число.






Получим ресурс в коде Java



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.content.res.Resources;
import android.os.Bundle;
import android.widget.TextView;

import java.util.Calendar;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);

        String userName = "Евгений";
        Calendar calendar = Calendar.getInstance();
        int hour = calendar.get(Calendar.HOUR_OF_DAY);
        int minute = calendar.get(Calendar.MINUTE);

        String text = getString(R.string.welcome_message, userName, hour, minute);
        TextView textView = new TextView(this);
        textView.setText(text);
        textView.setTextSize(28);
        setContentView(textView);
    }
}
```



Метод `getString(R.string.welcome_message, userName, hour, minute)` получает ресурс welcome_message и в качестве последующих параметров передает его аргументам значения. Для первого аргумента-строки используется переменная userName, а для второго и третьего аргументов передаем текущее количество часов и минут, полученных с помощью класса Calendar.



![форматирование ресурса в string.xml в android и java](/uploads/course-lectures/44c05f5b889ef1f2b58258760b26903e16c1f6c0.png)



### Ресурсы Plurals



Plurals представляют еще один вид набора строк. Он предназначен для описания количества элементов. Для чего это надо? К примеру, возьмем существительное: нередко оно изменяет окончание в зависимости от числительного, которое с ним употребляется: 1 цветок, 2 цветка, 5 цветков. Для подобных случаев и используется ресурс `plurals`.



Посмотрим на примере. Добавим в папку res/values новый ресурс. Назовем его **flowers**:



![ресурс plurals в android studio](/uploads/course-lectures/ffd038d20120a20f10207a1e6f83c86ab4073c1d.png)



Изменим его содержимое следующим образом:



```xml

<?xml version="1.0" encoding="utf-8"?>
<resources>
    <plurals name="flowers">
        <item quantity="one">%d цветок</item>
        <item quantity="few">%d цветка</item>
        <item quantity="many">%d цветков</item>
    </plurals>
</resources>
```



Для задания ресурса используется элемент ` `, для которого существует атрибут `name`, получающий в качестве значения произвольное название, по которому потом ссылаются на данный ресурс.



Сами наборы строк вводятся дочерними элементами ` `. Этот элемент имеет атрибут `quantity`, который имеет значение, указывающее, когда эта строка используется. Данный атрибут может принимать следующие значения:





- zero : строка для количества в размере 0

- one : строка для количества в размере 1 (для русского языка - для задания всех количеств, оканчивающихся на 1, кроме 11)

- two : строка для количества в размере 2

- few : строка для небольшого количества

- many : строка для больших количеств

- other : все остальные случаи



Причем в данном случае многое зависит от конкретного языка. А система сама позволяет определить, какое значение брать для того или иного числа.



Использование данного ресурса возможно толко в коде java. Поэтому изменим код MainActivity:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);
        String rose = getResources().getQuantityString(R.plurals.flowers, 21, 21);

        TextView textView = new TextView(this);
        textView.setText(rose);
        textView.setTextSize(26);
        setContentView(textView);
    }
}
```



С помощью метода **getQuantityString** мы получаем значение ресурса. Первым параметром передаем идентификатор ресурса. Вторым параметром идет значение. для которого нужно найти нужную строку. Третий параметр представляет собой значение, которое будет вставляться на место плейсхолдера **%d**. То есть мы получаем строку для числа 21.



![определение ресурса plurals в android](/uploads/course-lectures/8150df2f9e3d1c62297aaa4a15b86015a10028cd.png)



### string array



Еще одним видом строковых ресурсов является **string-array** или массив строк. Например, добавим в папку **res/values** новый файл, который назовем **languages.xml**:



![определение ресурса string array в android и java](/uploads/course-lectures/3e92d9d3063a37192a551165f006eda08eea1a3e.png)



Пусть он будет содержать следующий код:



```xml

<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string-array name="languages">
        <item>Java</item>
        <item>Kotlin</item>
        <item>Dart</item>
    </string-array>
</resources>
```



Ресурс задается с помощью элемента ** **. Фактически он определяет набор строк. А каждая отдельная строка задается с помощью элемента ** **



В файле **MainActivity.java** определим код для получения значений из этого ресурса:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.content.res.Resources;
import android.os.Bundle;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);
        Resources res = getResources();
        String[] languages = res.getStringArray(R.array.languages);
        String allLangs = "";
        for (String lang: languages) {
            allLangs += lang + " ";
        }
        TextView textView = new TextView(this);
        textView.setText(allLangs);
        textView.setTextSize(28);
        setContentView(textView);
    }
}
```



С помощью метода **getStringArray** получаем ресурс в массив строк и затем с помощью цикла складдываем из массива одну строку и передаем ее в TextView.



![получение ресурса string array и getstringarray в android и java](/uploads/course-lectures/fa3ad09e63514eadee6c51647a943509411ad697.png)

Определение размеров должно находиться в папке **res/values** в файле с любым произвольным именем. Общий синтаксис определения ресурса следующий:

```xml
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <dimen name="имя_ресурса">используемый_размер</dimen>
</resources>
```

Как и другие ресурсы, ресурс dimension определяется в корневом элементе ` `. Тег ` ` обозначает ресурс и в качестве значния принимает некоторое значение размера в одной из принятых единиц измерения (dp, sp, pt, px, mm, in). Более подробно установка размеров рассматривалась в одной из прошлых статей - Определение размеров

Так, добавим в Android Studio в папку **res/values** новый элемент **Values Resources File**, который назовем **dimens.xml**.

![ресурс dimension в android studio и java, dimens.xml](/uploads/course-lectures/438c7ed30f207a42fd0866eac23b3bb8b6ede852.png)

Определим в нем следующее содержимое:

```xml
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <dimen name="horizontal_margin">64dp</dimen>
    <dimen name="vertical_margin">32dp</dimen>
    <dimen name="text_size">32sp</dimen>
</resources>
```

Здесь определены два ресурса для отступов `horizontal_margin` и `vertical_margin`, которые хранят соответственно значения 64dp и 32dp, и ресурс text_size, который хранит высоту шрифта - 32sp. Названия ресурсов могут быть произвольными.

Используем ресурс в файле activity_main.xml:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <TextView
        android:id="@+id/textView"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Hello Android"
        android:background="#eaeaea"

        android:layout_marginTop="@dimen/vertical_margin"
        android:layout_marginLeft="@dimen/horizontal_margin"
        android:textSize="@dimen/text_size"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

Ресурсы dimension используются для таких атриубтов визуальных элементов, которые в качестве значения требуют указание числового значения. Например, атриубут `android:layout_height` или `android:textSize`. Для получения ресурса в xml после `"@dimen/"` указывается имя ресурса.

![dimensions в android и java](/uploads/course-lectures/30d5e088243203d37eeec74c40772faac61900ae.png)

Для получения ресурсов в коде java применяется метод **getDimension()** класса Resources. Например, определим в коде Java аналогичный визуальный интерфейс:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import androidx.constraintlayout.widget.ConstraintLayout;

import android.content.res.Resources;
import android.os.Bundle;
import android.util.TypedValue;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);
        // получаем ресурсы
        Resources resources = getResources();
        float textSize = resources.getDimension(R.dimen.text_size);
        int hMargin = (int)resources.getDimension(R.dimen.horizontal_margin);
        int vMargin = (int)resources.getDimension(R.dimen.vertical_margin);

        ConstraintLayout constraintLayout = new ConstraintLayout(this);

        ConstraintLayout.LayoutParams layoutParams = new ConstraintLayout.LayoutParams
                (ConstraintLayout.LayoutParams.WRAP_CONTENT , ConstraintLayout.LayoutParams.WRAP_CONTENT);
        layoutParams.leftToLeft = ConstraintLayout.LayoutParams.PARENT_ID;
        layoutParams.topToTop = ConstraintLayout.LayoutParams.PARENT_ID;

        TextView textView = new TextView(this);
        textView.setText("Hello Android");
        textView.setBackgroundColor(0XFFEAEAEA);
        // устанавливаем размер шрифт по ресурсу
        textView.setTextSize(TypedValue.COMPLEX_UNIT_PX, textSize);
        // устанавливаем отступы пв соответствии с ресурсами
        layoutParams.setMargins(hMargin, vMargin, hMargin, vMargin);

        textView.setLayoutParams(layoutParams);
        constraintLayout.addView(textView);

        setContentView(constraintLayout);
    }
}
```

При программном получении ресурсов dimen с помощью метода `getDimension()` следует учитывать, что он возвращает значения в физических пикселях, даже если в файле ресурсов мы определили значения в других величинах (32sp, 64dp). В большинстве случае это не вызовет каких-то трудностей, поскольку большинство методов в Java принимают именно пиксели, а не dp или другие единицы, как например, метод `setMargins()`, который устанавливает отступы.

Однако метод `setTextSize()` принимает именно **sp**, поэтому с помощью дополнительного параметра необходимо указать, что в данном случае имеются в виду физические пиксели, а не sp:

```java
textView.setTextSize(TypedValue.COMPLEX_UNIT_PX, textSize);
```

Либо, как вариант, с помощью класса **TypedValue** программно перевести физические пиксели в sp или другую единицу измерения.

В приложении Android также можно определять ресурсы цветов (Color). Они должны храниться в файле по пути **res/values** и также, как и ресурсы строк, заключены в тег ` `. Так, по умолчанию при создании самого простого проекта в папку **res/values** добавляется файл **colors.xml**:

```xml
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="purple_200">#FFBB86FC</color>
    <color name="purple_500">#FF6200EE</color>
    <color name="purple_700">#FF3700B3</color>
    <color name="teal_200">#FF03DAC5</color>
    <color name="teal_700">#FF018786</color>
    <color name="black">#FF000000</color>
    <color name="white">#FFFFFFFF</color>
</resources>
```

Цвет определяется с помощью элемента ` `. Его атрибут `name` устанавливает название цвета, которое будет использоваться в приложении, а шестнадцатеричное число - значение цвета.

Для задания цветовых ресурсов можно использовать следующие форматы:

- #RGB (#F00 - 12-битное значение)

- #ARGB (#8F00 - 12-битное значение с добавлением альфа-канала)

- #RRGGBB (#FF00FF - 24-битное значение)

- #AARRGGBB (#80FF00FF - 24-битное значение с добавлением альфа-канала)

Чтобы не трогать и не портить данный файл, определим свой новый файл ресурсов и для этого добавим в папку **res/values** новый файл ресурсов, который назовем **my_colors.xml**.

![использование цвета в android studio и ресурсы color](/uploads/course-lectures/6b1f73b3ff95b6c3f398b23b2b2e53384678fb8e.png)

Изменим файл **my_colors.xml**, добавив в него пару цветов:

```xml
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="textViewBackColor">#A0EAE1</color>
    <color name="textViewFontColor">#00695C</color>
</resources>
```

Применим цвета в файле **activity_main.xml**:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <TextView
        android:id="@+id/textView"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Hello Android"

        android:background="@color/textViewBackColor"
        android:textColor="@color/textViewFontColor"

        android:textSize="32sp"
        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintTop_toTopOf="parent" />

</androidx.constraintlayout.widget.ConstraintLayout>
```

С помощью атрибута `android:textColor` устанавливается цвет текста в TextView, а атрибут `android:background` устанавливает фон TextView. В качестве значения они используют цвет, например, в том же шестнадцатеричном формате. Для получения самого цвета после **"@color/"** указывается имя ресурса.

![использование цвета в android и java и ресурсы color](/uploads/course-lectures/d2778c5421c393c24928971dc311991af22b617c.png)

Также можно использовать цветовые ресурсы в коде MainActivity:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import androidx.constraintlayout.widget.ConstraintLayout;

import android.content.res.Resources;
import android.os.Bundle;
import android.widget.TextView;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_main);
        // получаем ресурсы
        Resources resources = getResources();
        int textColor = resources.getColor(R.color.textViewFontColor,  null);
        int backgroundColor = resources.getColor(R.color.textViewBackColor,  null);

        ConstraintLayout constraintLayout = new ConstraintLayout(this);

        ConstraintLayout.LayoutParams layoutParams = new ConstraintLayout.LayoutParams
                (ConstraintLayout.LayoutParams.WRAP_CONTENT , ConstraintLayout.LayoutParams.WRAP_CONTENT);
        layoutParams.leftToLeft = ConstraintLayout.LayoutParams.PARENT_ID;
        layoutParams.topToTop = ConstraintLayout.LayoutParams.PARENT_ID;

        TextView textView = new TextView(this);
        textView.setText("Hello Android");
        textView.setTextSize(32);

        // используем ресурсы color
        textView.setTextColor(textColor);
        textView.setBackgroundColor(backgroundColor);

        textView.setLayoutParams(layoutParams);
        constraintLayout.addView(textView);

        setContentView(constraintLayout);
    }
}
```

Для получения цвета из ресурсов применяется метод **resources.getColor()**, который принимает два параметра. Первый параметр - идентификатор ресурса, цвет которого надо получить. Второй параметр представляет тему. Но поскольку в данном случае тема не важна, для этого параметра передаем значение `null`

Следует учитывать, что метод **resources.getColor()** с двумя параметрами, который использован выше, доступен, если для минимальная версия Android не ниже Android 6.0 (или Android 23). Однако минимальная версия Android ниже, то можно использовать устаревшую версию с одним параметром:

```java
int textColor = resources.getColor(R.color.textViewFontColor);
// вместо
//int textColor = resources.getColor(R.color.textViewFontColor,  null);
```

Ключевым компонентом для создания визуального интерфейса в приложении Android является activity (активность). Нередко activity ассоциируется с отдельным экраном или окном приложения, а переключение между окнами будет происходить как перемещение от одной activity к другой. Приложение может иметь одну или несколько activity. Например, при создании проекта с пустой Activity в проект по умолчанию добавляется один класс Activity - MainActivity, с которого и начинается работа приложения:



```java

public class MainActivity extends AppCompatActivity {

    // содержимое класса
}
```



Все объекты activity представляют собой объекты класса **android.app.Activity**, которая содержит базовую функциональность для всех activity. В приложении из прошлой темы мы напрямую с этим классом не работали, а MainActivity наследовалась от класса **AppCompatActivity**. Однако сам класс AppCompatActivity, хоть и не напрямую, наследуется от базового класса Activity.



### Жизненный цикл приложения



Все приложения Android имеют строго определенный системой жизненный цикл. При запуске пользователем приложения система дает этому приложению высокий приоритет. Каждое приложение запускается в виде отдельного процесса, что позволяет системе давать одним процессам более высокой приоритет, в отличие от других. Благодаря этому, например, при работе с одними приложениями Android позволяет не блокировать входящие звонки. После прекращения работы с приложением, система освобождает все связанные ресурсы и переводит приложение в разряд низкоприоритетного и закрывает его.



Все объекты activity, которые есть в приложении, управляются системой в виде стека activity, который называется **back stack**. При запуске новой activity она помещается поверх стека и выводится на экран устройства, пока не появится новая activity. Когда текущая activity заканчивает свою работу (например, пользователь уходит из приложения), то она удаляется из стека, и возобновляет работу та activity, которая ранее была второй в стеке.



После запуска activity проходит через ряд событий, которые обрабатываются системой и для обработки которых существует ряд обратных вызовов:



```java

protected void onCreate(Bundle saveInstanceState);
protected void onStart();
protected void onRestart();
protected void onResume();
protected void onPause();
protected void onStop();
protected void onDestroy();
```



Схематично взаимосвязь между всеми этими обратными вызовами можно представить следующим образом



![жизненный цикл приложения android](/uploads/course-lectures/ec0068dd6df62e431a35012eec947c3e6f9c0832.png)



### onCreate()



**onCreate** - первый метод, с которого начинается выполнение activity. В этом методе activity переходит в состояние Created. Этот метод обязательно должен быть определен в классе activity. В нем производится первоначальная настройка activity. В частности, создаются объекты визуального интерфейса. Этот метод получает объект `Bundle`, который содержит прежнее состояние activity, если оно было сохранено. Если activity заново создается, то данный объект имеет значение null. Если же activity уже ранее была создана, но находилась в приостановленном состоянии, то bundle содержит связанную с activity информацию.



После того, как метод onCreate() завершил выполнение, activity переходит в состояние `Started`, и и система вызывает метод `onStart()`



### onStart



В методе **onStart()** осуществляется подготовка к выводу activity на экран устройства. Как правило, этот метод не требует переопределения, а всю работу производит встроенный код. После завершения работы метода activity отображается на экране, вызывается метод **onResume**, а activity переходит в состояние Resumed.



### onResume



При вызове метода `onResume` activity переходит в состояние `Resumed` и отображается на экране устройства, и пользователь может с ней взаимодействовать. И собственно activity остается в этом состоянии, пока она не потеряет фокус, например, вследствии переключения на другую activity или просто из-за выключения экрана устройства.



### onPause



Если пользователь решит перейти к другой activity, то система вызывает метод **onPause**, а activity переходит в состояние `Paused`. В этом методе можно освобождать используемые ресурсы, приостанавливать процессы, например, воспроизведение аудио, анимаций, останавливать работу камеры (если она используется) и т.д., чтобы они меньше сказывались на производительность системы.

 

Но надо учитывать, что в этот состоянии activity по прежнему остается видимой на экране, и на работу данного метода отводится очень мало времени, поэтому не стоит здесь сохранять какие-то данные, особенно если при этом требуется обращение к сети, например, отправка данных по интернету, или обращение к базе данных - подобные действия лучше выполнять в методе `onStop()`.



После выполнения этого метода activity становится невидимой, не отображается на экране, но она все еще активна. И если пользователь решит вернуться к этой activity, то система вызовет снова метод `onResume`, и activity снова появится на экране.



Другой вариант работы может возникнуть, если вдруг система видит, что для работы активных приложений необходимо больше памяти. И система может сама завершить полностью работу activity, которая невидима и находится в фоне. Либо пользователь может нажать на кнопку Back (Назад). В этом случае у activity вызывается метод **onStop**.






### onStop



В этом методе activity переходит в состояние Stopped. В этом состоянии activity полностью невидима. В методе onStop следует особождать используемые ресурсы, которые не нужны пользователю, когда он не взаимодействует с activity. Здесь также можно сохранять данные, например, в базу данных.



При этом во время состояния Stopped activity остается в памяти устройства, сохраняется состояние всех элементов интерфейса. К примеру, если в текстовое поле EditText был введен какой-то текст, то после возобновления работы activity и перехода ее в состояние Resumed мы вновь увидим в текстовом поле ранее введенный текст.



Если после вызова метода **onStop** пользователь решит вернуться к прежней activity, тогда система вызовет метод **onRestart**. Если же activity вовсе завершила свою работу, например, из-за закрытия приложения, то вызывается метод **onDestroy()**.

 

### onDestroy



Ну и завершается работа activity вызовом метода **onDestroy**, который возникает либо, если система решит убить activity в силу конфигурационных причин (например, поворот экрана или при многоконном режиме), либо при вызове метода **finish()**.



Также следует отметить, что при изменении ориентации экрана система завершает activity и затем создает ее заново, вызывая метод **onCreate**.



В целом переход между состояниями activity можно выразить следующей схемой:



![состояния activity в android](/uploads/course-lectures/f1b620705d30f1d0d9b9497d13bb637b4d235715.png)



Расмотрим несколько ситуаций. Если мы работаем с Activity и затем переключаемся на другое приложение, либо нажимаем на кнопку Home, то у Activity вызывается следующая цепочка методов: **onPause -> onStop**. Activity оказывается в состоянии Stopped. Если пользователь решит вернуться к Activity, то вызывается следующая цепочка методов: **onRestart -> onStart -> onResume**.



Другая ситуация, если пользователь нажимает на кнопку Back (Назад), то вызывается следующая цепочка **onPause -> onStop -> onDestroy**. В результате Activity уничтожается. Если мы вдруг захотим вернуться к Activity через диспетчер задач или заново открыв приложение, то activity будет заново пересоздаваться через методы **onCreate -> onStart -> onResume**



### Управление жизненным циклом



Мы можем управлять этими событиями жизненного цикла, переопределив соответствующие методы. Для этого возьмем из прошлой главы класс MainActivity и изменим его следующим образом:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.util.Log;


public class MainActivity extends AppCompatActivity {

    private final static String TAG = "MainActivity";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        Log.d(TAG, "onCreate");
    }
    @Override
    protected void onDestroy(){
        super.onDestroy();
        Log.d(TAG, "onDestroy");
    }
    @Override
    protected void onStop(){
        super.onStop();
        Log.d(TAG, "onStop");
    }
    @Override
    protected void onStart(){
        super.onStart();
        Log.d(TAG, "onStart");
    }
    @Override
    protected void onPause(){
        super.onPause();
        Log.d(TAG, "onPause");
    }
    @Override
    protected void onResume(){
        super.onResume();
        Log.d(TAG, "onResume");
    }

    @Override
    protected void onRestart(){
        super.onRestart();
        Log.d(TAG, "onRestart");
    }
}
```



Для логгирования событий здесь используется класс **android.util.Log**.



В данном случае обрабатываются все ключевые методы жизненного цикла. Вся обработка сведена к вызову метода `Log.d()`, в который передается TAG - случайное строковое значение и строка, которая выводится в консоли **Logcat** в нижней части Android Studio, выполняя роль отладочной информации. Если эта консоль по умолчанию скрыта, то мы можем перейти к ней через пункт меню **View -> Tool Windows -> Logcat**.



И при запуске приложения мы сможем увидеть в окне **Logcat** отладочную информацию, которая определяется в методах жизненного цикла activity:



![отладка приложений на android](/uploads/course-lectures/cad5b7e787061333a7de661c5190574ba0e190cf.png)

Для взаимодействия между различными объектами activity ключевым классом является **android.content.Intent**. Он представляет собой задачу, которую надо выполнить приложению.

Для работы с Intent добавим новый класс Activity. Для этого нажмем правой кнопкой мыши в папку, в которой находится класс MainActivity, и затем в контекстном меню выберем **New->Activity->Empty Views Activity**:

![добавление empty activity в android studio](/uploads/course-lectures/a764f1d4cf922384a31b71d56d1d27372bfa685a.png)

Новый класс Activity назовем **SecondActivity**, а все остальные настройки оставим по умолчанию:

![установка empty activity в android studio](/uploads/course-lectures/8e63286d73554c6dcf6dd2fc4821f0d76e7cabb6.png)

И после этого в проект будет добавлена новая Activity - SecondActivity:

![mainactivity в android studio](/uploads/course-lectures/e38a4b231ca6e3c54704c62b309a48831fda9569.png)

После этого в файле манифеста **AndroidManifest.xml** мы сможем найти следующие строки:

```xml
<activity
    android:name=".SecondActivity"
    android:exported="false" />
<activity
    android:name=".MainActivity"
    android:exported="true">
    <intent-filter>
        <action android:name="android.intent.action.MAIN" />

        <category android:name="android.intent.category.LAUNCHER" />
    </intent-filter>
</activity>
```

Все используемые классы activity должны быть описаны в файле AndroidManifest.xml с помощью элемента ` `. Каждый подобный элемент содержит как минимум один атрибут `android:name`, который устанавливает имя класса activity.

Однако по сути activity - это стандартные классы java, которые наследуются от класса **Activity** или его наследников. Поэтому вместо встроенных шаблонов в Android Studio можем добавлять обычные классы, и затем их наследовать от класса Activity. Однако в этом случае нужно будет вручную добавлять в файл манифеста данные об activity.

Причем для MainActivity в элементе **intent-filter** определяется интент-фильтр. В нем элемент action значение "android.intent.action.MAIN" представляет главную точку входа в приложение. То есть MainActivity остается основной и запускается приложением по умолчанию.

Для SecondActivity просто указано, что она в проекте, и никаких intent-фильтров для нее не задано.

Чтобы из MainActivity запустить SecondActivity, надо вызвать метод `startActivity()`:

```java
Intent intent = new Intent(this, SecondActivity.class);
startActivity(intent);
```

В качестве параметра в метод startActivity передается объект Intent. Для своего создания Intent в конструкторе принимает два параметра: контекст выполнения (в данном случае это текущий объект MainActivity) и класс, который используется объектом Intent и представляет передаваемые в задачу данные (фактически класс activity, которую мы будем запускать).

Теперь рассмотрим реализацию перехода от одной Activity к другой. Для этого в файле **activity_main.xml** (то есть в интерфейсе для MainActivity) определим кнопку:

```xml
<?xml version="1.0" encoding="utf-8"?>
<androidx.constraintlayout.widget.ConstraintLayout
    xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:app="http://schemas.android.com/apk/res-auto"
    android:layout_width="match_parent"
    android:layout_height="match_parent">

    <Button
        android:id="@+id/navButton"
        android:textSize="20sp"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="Перейти к SecondActivity"
        android:onClick="onClick"

        app:layout_constraintLeft_toLeftOf="parent"
        app:layout_constraintRight_toRightOf="parent"
        app:layout_constraintTop_toTopOf="parent"/>

</androidx.constraintlayout.widget.ConstraintLayout>
```

И определим для кнопки в классе **MainActivity** обработчик нажатия, по которому будет производиться переход к новой Activity:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.content.Intent;
import android.os.Bundle;
import android.view.View;

public class MainActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
    }
    public void onClick(View view) {
        Intent intent = new Intent(this, SecondActivity.class);
        startActivity(intent);
    }
}
```

В обработчике нажатия будет запускаться SecondActivity.

Далее изменим код **SecondActivity**:

```java
package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.TextView;

public class SecondActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        //setContentView(R.layout.activity_second);
        TextView textView = new TextView(this);
        textView.setTextSize(20);
        textView.setPadding(16, 16, 16, 16);
        textView.setText("SecondActivity");
        setContentView(textView);
    }
}
```

Запустим приложение и перейдем от одной Activity к другой:

![intent и startactivity в android и java](/uploads/course-lectures/e8f24464e83a41ced9c971f5a9b98703f8d5b735.png)

Для передачи данных между двумя Activity используется объект **Intent**. Через его метод **putExtra()** можно добавить ключ и связанное с ним значение.



Например, передача из текущей activity в SecondActivity строки "Hello World" с ключом "hello":



```java

// создание объекта Intent для запуска SecondActivity
Intent intent = new Intent(this, SecondActivity.class);
// передача объекта с ключом "hello" и значением "Hello World"
intent.putExtra("hello", "Hello World");
// запуск SecondActivity
startActivity(intent);
```



Для передачи данных применяется метод **putExtra()**, который в качестве значения позволяет передать данные простейших типов - String, int, float, double, long, short, byte, char, массивы этих типов, либо объект интерфейса Serializable.



Чтобы получить отправленные данные при загрузке SecondActivity, можно воспользоваться методом **get()**, в который передается ключ объекта:



```java

Bundle arguments = getIntent().getExtras();
String name = arguments.get("hello").toString();	// Hello World
```



В зависимости от типа отправляемых данных при их получении мы можем использовать ряд методов объекта Bundle. Все они в качестве параметра принимают ключ объекта. Основные из них:





- get() : универсальный метод, который возвращает значение типа Object. Соответственно поле получения данное значение необходимо преобразовать к нужному типу

- getString() : возвращает объект типа String

- getInt() : возвращает значение типа int

- getByte() : возвращает значение типа byte

- getChar() : возвращает значение типа char

- getShort() : возвращает значение типа short

- getLong() : возвращает значение типа long

- getFloat() : возвращает значение типа float

- getDouble() : возвращает значение типа double

- getBoolean() : возвращает значение типа boolean

- getCharArray() : возвращает массив объектов char

- getIntArray() : возвращает массив объектов int

- getFloatArray() : возвращает массив объектов float

- getSerializable() : возвращает объект интерфейса Serializable



Пусть у нас в проекте будет определено две activity: MainActivity и SecondActivity.



В коде SecondActivity определим получение данных:



```java

package com.example.viewapp;

import androidx.appcompat.app.AppCompatActivity;

import android.os.Bundle;
import android.widget.TextView;

public class SecondActivity extends AppCompatActivity {

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
		
        TextView textView = new TextView(this);
        textView.setTextSize(26);
        textView.setPadding(16, 16, 16, 16);

        Bundle arguments = getIntent().getExtras();

        if(arguments!=null){
            String name = arguments.get("name").toString();
            String company = arguments.getString("company");
            int age = arguments.getInt("age");
            textView.setText("Name: " + name + "\nCompany: " + company +
                    "\nAge: " + age);
        }

        setContentView(textView);
    }
}
```



В данном случае в SecondActivity получаем все данных из объекта Bundle и выводим их в текстовое поле TextView. Предполагается, что данной activity будут передаваться три элемента - две строки с ключами name и company и число с ключом price.






